const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  return [{ json: { user_id: payload.sub, tenant_id: payload.tenant_id, role: payload.role || 'architect', project_id: projectId, body: body, request_id: 'req_' + Math.random().toString(36).slice(2, 10) }}];
} catch (e) { return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message }}]; }

const sess = $('Decode JWT + Body').first().json;
const projectRows = $('Load Project').all().map(i => i.json).filter(p => p && p.id);
if (projectRows.length === 0) return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe', request_id: sess.request_id }}];
const project = projectRows[0];
const designRows = $('Load Design').all().map(i => i.json).filter(d => d && d.id);
const tradeRows = $input.all().map(i => i.json).filter(t => t && t.trade_type);
const design = designRows[0] || null;
const phase = sess.body && sess.body.phase ? sess.body.phase : (project.current_phase || 'demolicion');
const systemPrompt = 'Eres agent_qc_checklists. Generas checklists de control de calidad para una fase concreta de obra. Fases tipicas: demolicion (residuos, integridad estructural), albanileria (alineamientos, niveles), instalaciones (estanqueidad, aislamiento), pavimentos (nivelacion, juntas), pintura (imprimacion, capas), entrega (documentacion, fotos). 8-15 items con criterio aprobacion y herramienta verificacion. DEVUELVE SOLO JSON.';
const userPrompt = 'PROYECTO: ' + project.name + String.fromCharCode(10) + 'FASE OBJETIVO: ' + phase + String.fromCharCode(10) + 'DESIGN: ' + (design ? design.title + ' - ' + ((design.intervention_logic || '').slice(0, 300)) : '(sin design seleccionado)') + String.fromCharCode(10) + 'TRADES: ' + JSON.stringify(tradeRows.map(function(t){return t.trade_type;})) + String.fromCharCode(10,10) + 'Genera checklist QC para la fase "' + phase + '".' + String.fromCharCode(10,10) + 'OUTPUT JSON: { items: [{ id, description, criteria, tool, critical }], notes }';
return [{ json: { user_id: sess.user_id, tenant_id: sess.tenant_id, project_id: project.id, request_id: sess.request_id, body: sess.body, llm_payload: { model: 'gpt-4o', messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }], temperature: 0.2, max_tokens: 2000, response_format: { type: 'json_object' }}}}];

const llm = $input.first()?.json;
const built = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message, _raw: raw.slice(0,500), request_id: built.request_id }}];
}
const usage = llm?.usage || {};
return [{ json: {
  user_id: built.user_id,
  tenant_id: built.tenant_id,
  project_id: built.project_id,
  request_id: built.request_id,
  body: built.body,
  output: parsed,
  summary: { keys: Object.keys(parsed) },
  model: llm?.model || 'gpt-4o',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0
}}];
